/* ExamIA v0.2.1 — piloto LOCAL. Sin identidad verificada, sincronización ni integridad de servidor.
   Las evidencias nunca se envían a GitHub. No hay reconocimiento de identidad ni decisión de fraude. */
'use strict';
(() => {
const $ = id => document.getElementById(id);
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid = () => crypto.randomUUID();
const date = v => new Date(v).toLocaleString('es-PE');
const elapsed = ms => {const s = Math.max(0, Math.round((ms || 0)/1000)); return `${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`;};
const defaults = {camera:true, images:true, screen:false, ai:true, tabs:true, clipboard:true, blockPaste:false, fullscreen:false, interval:30};
const S = {user:null, exams:[], attempts:[], exam:null, attempt:null, camera:null, screen:null, detector:null, aiState:"idle", aiJob:null, aiEpoch:0, aiRetryTimer:null, aiRetryAt:0, aiLastFrame:0, aiVideoTime:-1, aiError:"", active:false, timers:[], urls:[], pending:new Set(), queue:Promise.resolve(), outside:null, currentQ:null, lastCapture:0, capturing:false, faceState:null, faceSince:0, faceLogged:false, mediaCount:0, savingError:false, submitting:false};
let database, aborter, saveTimer, toastTimer, prepResume=null, reviewId=null;
function toast(text){$('toast').textContent=text;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,6500);}
function fail(err){console.error(err);toast(err.message || String(err));}
function openDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open('examia-evidence-v2',1);r.onupgradeneeded=()=>{const d=r.result;d.createObjectStore('exams',{keyPath:'id'});d.createObjectStore('attempts',{keyPath:'id'});const m=d.createObjectStore('media',{keyPath:'id'});m.createIndex('attemptId','attemptId');};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);r.onblocked=()=>reject(new Error('Cierre otras pestañas de ExamIA y recargue.'));});}
function store(name,mode,fn){return new Promise((resolve,reject)=>{const t=database.transaction(name,mode);let r;try{r=fn(t.objectStore(name));}catch(e){reject(e);return;}t.oncomplete=()=>resolve(r?.result);t.onerror=()=>reject(t.error);t.onabort=()=>reject(t.error || new Error('No se completó el guardado'));});}
const all = name => store(name,'readonly',o=>o.getAll());
const get = (name,id) => store(name,'readonly',o=>o.get(id));
const put = (name,value) => store(name,'readwrite',o=>o.put(value));
const del = (name,id) => store(name,'readwrite',o=>o.delete(id));
const mediaFor = id => store('media','readonly',o=>o.index('attemptId').getAll(id));
function persist(a=S.attempt){if(!a)return Promise.resolve();a.savedAt=Date.now();const snapshot=structuredClone(a);S.queue=S.queue.catch(()=>{}).then(()=>put('attempts',snapshot));S.queue.then(()=>{if($('save-state'))$('save-state').textContent='Guardado local: '+new Date(snapshot.savedAt).toLocaleTimeString('es-PE');}).catch(e=>{S.savingError=true;if($('save-state'))$('save-state').textContent='ERROR al guardar. Exporte antes de cerrar.';toast('No se pudo guardar: '+e.message);});return S.queue;}
function journal(){if(S.active && S.attempt)try{localStorage.setItem('examia-v2-recovery',JSON.stringify(S.attempt));}catch{toast('La copia de recuperación está llena. No cierre el examen.');}}
function autosave(){if(S.attempt)S.attempt.savedAt=Date.now();journal();clearTimeout(saveTimer);saveTimer=setTimeout(()=>persist().catch(()=>{}),350);}
function mediaHome(){const d=$('media-dock');$('media-home').append(d);d.hidden=true;}
function mediaAt(id){const host=$(id);if(!host)return;host.append($('media-dock'));$('media-dock').hidden=false;$('media-dock').querySelector('.grid').style.gridTemplateColumns=id==='exam-media'?'1fr':'';}
function view(html){mediaHome();S.urls.forEach(u=>URL.revokeObjectURL(u));S.urls=[];$('view').innerHTML=html;}
function stopMedia(){S.aiEpoch++;clearTimeout(S.aiRetryTimer);S.aiRetryTimer=null;S.aiJob=null;S.aiState="idle";S.aiRetryAt=0;S.aiLastFrame=0;S.aiVideoTime=-1;S.aiError="";S.active=false;aborter?.abort();S.timers.forEach(clearInterval);S.timers=[];for(const k of ['camera','screen']){S[k]?.getTracks().forEach(t=>t.stop());S[k]=null;$(k+'-video').srcObject=null;}if(S.detector){S.detector.close();S.detector=null;}mediaHome();}
function cfg(exam){const c={...defaults,...exam.settings};c.ai=!!c.camera;return c;}
function teacherAIText(){return cfg(S.exam).camera?'IA automática y obligatoria: ausencia y múltiples rostros. Se inicia al autorizar la cámara; el estudiante no puede desactivarla. Sin reconocimiento de identidad ni penalización automática.':'Sin cámara: no se realiza análisis visual con IA.';}
const seed = () => ({id:uid(),title:'Prueba de supervisión y evidencias',course:'Proyecto Integrador',minutes:15,published:true,settings:{...defaults},questions:[{id:uid(),type:'choice',text:'¿Qué protocolo se utiliza para mensajería en IoT?',options:['FTP','MQTT','SMTP','POP3'],correct:1,points:5},{id:uid(),type:'text',text:'Explica una ventaja del diseño modular. Usa esta respuesta para probar el registro de copiar y pegar.',options:[],correct:0,points:5}]});
async function init(){try{database=await openDB();S.exams=await all('exams');if(!S.exams.length){let old;try{old=JSON.parse(localStorage.getItem('examia-demo-v1')||'null');}catch{}if(old?.exams?.length){for(const e of old.exams){await put('exams',{...e,settings:{...defaults,camera:!!e.camera,tabs:e.tabs!==false},questions:e.questions||[]});}for(const a of old.attempts||[]){await put('attempts',{...a,id:uid(),startedAt:Date.parse(a.date)||Date.now(),status:'legacy',events:(a.events||[]).map(x=>({id:uid(),type:'legacy',label:x.event,at:Date.parse(x.time)||Date.now(),level:'info',detail:'Registro de v0.1; no había imágenes ni respuestas completas guardadas.',media:[]})),exam:{questions:[]},answers:{},review:{state:'Pendiente',note:''}});} }else await put('exams',seed());}
let recovery;try{recovery=JSON.parse(localStorage.getItem('examia-v2-recovery')||'null');}catch{}if(recovery?.id && recovery.status==='running'){const existing=await get('attempts',recovery.id);if(!existing||existing.status==='running'&&existing.savedAt<recovery.savedAt)await put('attempts',recovery);}
const expired=(await all('media')).filter(m=>m.expiresAt<Date.now());for(const m of expired)await del('media',m.id);
S.exams=await all('exams');login();}catch(e){view(`<div class="notice error"><h2>No se puede abrir el almacenamiento</h2><p>${esc(e.message)}</p><p>Permita almacenamiento del sitio. No empiece un examen sin poder guardar.</p></div>`);}}
function login(){stopMedia();$('nav').hidden=true;view(`<div class="grid"><section class="card"><span class="tag">Acceso de prueba</span><h1>Revisa hechos, no solo contadores.</h1><p>Historial por pregunta, capturas de cámara y pantalla, portapapeles e informe descargable.</p><div class="notice warning">Este acceso <b>no autentica</b> una cuenta UPCH. Los roles sirven para probar el flujo en este equipo.</div></section><section class="card"><h2>Entrar al piloto</h2><label>Correo de prueba UPCH<input id="email" type="email" value="demo@upch.pe" autocomplete="email"></label><label>Perfil simulado<select id="role"><option value="docente">Docente</option><option value="estudiante">Estudiante</option><option value="administrador">Administrador</option></select></label><button data-act="enter">Ingresar</button><p class="muted">No ingrese contraseñas ni datos reales de estudiantes en este piloto.</p></section></div>`);}
function enter(){const email=$('email').value.trim().toLowerCase();if(!/^[^@\s]+@upch\.pe$/.test(email))return toast('Use un correo @upch.pe para esta prueba.');S.user={email,role:$('role').value};$('nav').hidden=false;$('identity').textContent=`${email} · ${S.user.role} (simulado)`;home();}
function button(act,label,id='',extra='secondary'){return `<button class="${extra}" data-act="${act}" data-id="${esc(id)}">${label}</button>`;}
async function home(){if(S.active)return toast('Entregue el examen antes de salir.');stopMedia();S.exams=await all('exams');S.attempts=await all('attempts');const pending=S.attempts.filter(a=>a.status==='running'&&a.student===S.user.email);view(`<div class="row between"><div><span class="muted">ESPACIO DE PRUEBAS</span><h1>Exámenes</h1></div>${S.user.role!=='estudiante'?button('create','Crear examen','',''):''}</div>${pending.map(a=>`<div class="notice warning"><b>Intento sin terminar: ${esc(a.title)}</b><p>Se mantiene el plazo original; no se reinicia el reloj.</p>${button('resume','Reanudar intento',a.id)}</div>`).join('')}<div class="grid">${S.exams.filter(e=>S.user.role!=='estudiante'||e.published).map(e=>{const c=cfg(e);return `<article class="card"><span class="tag ${e.published?'ok':''}">${e.published?'Publicado localmente':'Borrador'}</span><h2>${esc(e.title)}</h2><p>${esc(e.course)} · ${e.minutes} min · ${e.questions.length} preguntas</p><p>${[c.camera?'Cámara obligatoria':'Sin cámara',c.images&&c.camera?'Fotos por evento':'',c.screen?'Pantalla completa compartida':'',c.ai&&S.user.role!=='estudiante'?'IA obligatoria':'',c.clipboard?'Registro copiar/pegar':''].filter(Boolean).map(x=>`<span class="tag">${x}</span>`).join('')}</p><div class="row">${button('prepare',S.user.role==='estudiante'?'Rendir examen':'Probar examen',e.id,'')}${S.user.role!=='estudiante'?button('edit','Editar y configurar',e.id):''}</div></article>`;}).join('')}</div><div class="notice">Para comprobar evidencias: pruebe un examen, autorice la cámara, escriba o pegue una respuesta, salga a otra pestaña y vuelva. Al entregar, abra <b>Entregas y evidencias → Revisar</b>.</div>`);}
function edit(id){S.exam=structuredClone(S.exams.find(e=>e.id===id)||{...seed(),title:'Nuevo examen',published:false,questions:[]});editor();}
function checkbox(key,label,desc=''){return `<label><input type="checkbox" data-setting="${key}" ${cfg(S.exam)[key]?'checked':''}>${label}${desc?`<small>${desc}</small>`:''}</label>`;}
function editor(){const e=S.exam,c=cfg(e);e.settings=c;view(`<h1>Editor de examen</h1><div class="grid"><section class="card"><h2>Datos generales</h2><label>Título<input data-exam="title" value="${esc(e.title)}"></label><label>Curso<input data-exam="course" value="${esc(e.course)}"></label><label>Duración (minutos)<input type="number" min="1" max="360" data-exam="minutes" value="${e.minutes}"></label><label><input type="checkbox" data-exam="published" ${e.published?'checked':''}>Disponible en este navegador</label></section><section class="card"><h2>Supervisión configurable</h2>${checkbox('camera','Cámara obligatoria')}${checkbox('images','Guardar fotos de cámara','Fotos al iniciar, al entregar, en eventos y periódicamente. Requiere cámara.')}${checkbox('screen','Exigir compartir una pantalla completa','El estudiante debe elegir una pantalla con permiso explícito. No se capturan otras pantallas físicas.')}<div id="teacher-ai-policy" class="notice">${teacherAIText()}</div>${checkbox('tabs','Registrar pérdida de foco y visibilidad')}${checkbox('clipboard','Registrar copiar, cortar y pegar dentro del examen')}${checkbox('blockPaste','Bloquear pegado dentro de las respuestas','No impide usar otro dispositivo ni todas las formas de introducir texto.')}${checkbox('fullscreen','Solicitar pantalla completa al iniciar')}<label>Captura periódica (segundos)<input type="number" min="15" max="120" data-setting="interval" value="${c.interval}"></label><small>Fotos locales por 7 días, máximo 240 por intento. Sin audio. No hay vigilancia fuera de una evaluación iniciada.</small></section></div><h2>Preguntas</h2>${e.questions.map((q,i)=>`<section class="card"><div class="row between"><b>Pregunta ${i+1}</b>${button('remove-question','Eliminar',String(i),'secondary small')}</div><label>Enunciado<textarea data-q="${i}" data-field="text">${esc(q.text)}</textarea></label><div class="grid"><label>Tipo<select data-q="${i}" data-field="type">${[['choice','Opción múltiple'],['boolean','Verdadero / Falso'],['text','Desarrollo']].map(([v,t])=>`<option value="${v}" ${q.type===v?'selected':''}>${t}</option>`).join('')}</select></label><label>Puntos<input type="number" min="0.1" max="100" step="0.1" data-q="${i}" data-field="points" value="${q.points}"></label></div>${q.type==='text'?'<small>La respuesta se conservará completa y se calificará manualmente.</small>':q.options.map((o,j)=>`<label class="row"><input type="radio" name="correct-${i}" data-q="${i}" data-correct="${j}" ${q.correct===j?'checked':''}><input aria-label="Alternativa ${j+1}" data-q="${i}" data-option="${j}" value="${esc(o)}" style="width:85%"></label>`).join('')}</section>`).join('')}<div class="toolbar">${button('add-question','Añadir pregunta')}${button('save-exam','Guardar examen','','')}${button('home','Cancelar')}</div>`);}
async function saveExam(){const e=S.exam,c=cfg(e);if(!e.title.trim()||!Number.isFinite(e.minutes)||e.minutes<1||e.minutes>360||!e.questions.length)return toast('Complete título, duración (1–360) y al menos una pregunta.');if(!Number.isFinite(c.interval)||c.interval<15||c.interval>120)return toast('Intervalo entre 15 y 120 segundos.');for(const q of e.questions){if(!q.text.trim()||!Number.isFinite(q.points)||q.points<=0||q.type!=='text'&&(!q.options.length||q.options.some(o=>!o.trim())))return toast('Complete enunciados, alternativas y puntos positivos.');}if(!c.camera){c.images=false;c.ai=false;}if(c.blockPaste)c.clipboard=true;e.settings=c;await put('exams',e);toast('Examen guardado localmente.');await home();}
async function prepare(id,resume=null){stopMedia();prepResume=resume;S.exam=resume?structuredClone(resume.exam):structuredClone(S.exams.find(e=>e.id===id));if(!S.exam?.questions?.length)return toast('El examen no tiene preguntas.');const c=cfg(S.exam);S.exam.settings=c;view(`<h1>${esc(S.exam.title)}</h1><div class="grid"><section class="card"><h2>Antes de comenzar</h2><p>${S.exam.minutes} minutos · ${S.exam.questions.length} preguntas.</p><div class="notice warning"><b>Consentimiento de prueba</b><p>Durante este examen se registrarán ${c.tabs?'salidas de foco y visibilidad, ':''}${c.clipboard?'acciones de copiar/cortar/pegar (solo tipo y cantidad de caracteres, no el contenido del portapapeles), ':''}respuestas y eventos técnicos.</p><p>${c.camera&&c.images?'Se guardarán fotografías de la cámara. ':''}${c.screen?'Se guardarán capturas de la pantalla que elija compartir. Cierre información privada y notificaciones. ':''}${c.ai?'La cámara se analiza automáticamente para detectar ausencia o múltiples rostros; las incidencias las revisa el docente. No se identifica a personas ni se decide fraude automáticamente. El modelo se descarga de jsDelivr y Google; las imágenes se procesan en este dispositivo. ':''}</p><p>Los datos quedan en este navegador. Las imágenes caducan a los 7 días al volver a abrir la aplicación. Los informes exportados no caducan automáticamente. No hay audio ni envío de imágenes al repositorio.</p></div><label><input id="consent" type="checkbox">He leído qué datos se capturan y acepto participar en esta prueba.</label><div class="toolbar">${c.camera?button('camera','Autorizar cámara','',''):''}${c.screen?button('screen','Compartir pantalla','',''):''}</div><p id="prep-status" role="status"></p><p id="ai-status" class="muted">${c.ai?'La supervisión se preparará automáticamente al autorizar la cámara.':'Examen sin supervisión visual.'}</p><div class="row">${button('begin',resume?'Reanudar con plazo original':'Iniciar examen','','')}${button('home','Cancelar')}</div></section><section class="card"><h2>Vista previa</h2><div id="prep-media"></div><p class="muted">La vista previa no almacena fotos. Se verifica que la supervisión funciona antes de iniciar; las evidencias se guardan durante el examen. ${c.screen?'Compartir solo la pestaña del examen no permite ver lo que ocurre fuera de ella.':''}</p></section></div>`);mediaAt('prep-media');prepStatus();}
const live = key => !!S[key]?.getVideoTracks().some(t=>t.readyState==='live'&&!t.muted);
function prepStatus(){
const c=S.exam?cfg(S.exam):{};
if($('prep-status'))$('prep-status').textContent=`Cámara: ${c.camera?(live('camera')?'lista':'pendiente'):'no requerida'} · Pantalla: ${c.screen?(live('screen')?'compartida':'pendiente'):'no requerida'}`;
if($('consent')){const start=document.querySelector('[data-act="begin"]');if(start)start.disabled=!$('consent').checked||(c.camera&&!live('camera'))||(c.screen&&!live('screen'))||(c.ai&&(S.aiState!=='ready'||!S.detector));}
}
function aiStatus(){
if(!$('ai-status'))return;
const teacher=S.user?.role!=='estudiante';
const status={idle:'La supervisión se preparará automáticamente al autorizar la cámara.',loading:'Preparando supervisión automática…',ready:S.active?'Supervisión automática activa.':'Supervisión lista. Puede iniciar el examen.',error:'Supervisión no disponible. Revise su conexión; se reintentará automáticamente. Si persiste, contacte al docente.',stalled:'Esperando señal de cámara para restablecer la supervisión…'};
$('ai-status').textContent=status[S.aiState]||status.idle;
if(teacher&&S.aiError)$('ai-status').textContent+=' Detalle técnico: '+S.aiError;
}
function retryAI(){
clearTimeout(S.aiRetryTimer);S.aiRetryAt=Date.now()+8000;
S.aiRetryTimer=setTimeout(()=>{S.aiRetryTimer=null;if(S.exam&&cfg(S.exam).ai&&live('camera')&&(S.active||$('consent')?.checked))loadAI();},8000);
}
function resetFaceWindow(){S.faceState=null;S.faceSince=0;S.faceLogged=false;}
function checkAIFrame(detector){
const video=$('camera-video');
if(video.readyState<2||!video.videoWidth)throw new Error('No hay un fotograma de cámara disponible.');
const result=detector.detectForVideo(video,performance.now());
if(!Array.isArray(result?.detections))throw new Error('El modelo no devolvió un resultado válido.');
S.aiLastFrame=Date.now();S.aiVideoTime=video.currentTime;
}
async function setupMedia(key){if(!S.active&&!$('consent')?.checked)return toast('Lea y acepte el aviso antes de conceder permisos.');const c=cfg(S.exam);if(key==='camera'&&!c.camera||key==='screen'&&!c.screen)return;const epoch=S.aiEpoch;try{let stream;if(key==='camera'){if(!navigator.mediaDevices?.getUserMedia)throw new Error('Cámara no disponible. Abra el sitio con HTTPS.');stream=await navigator.mediaDevices.getUserMedia({video:{width:{ideal:640},height:{ideal:480}},audio:false});}else{if(!navigator.mediaDevices?.getDisplayMedia)throw new Error('Este navegador no permite compartir pantalla.');stream=await navigator.mediaDevices.getDisplayMedia({video:{displaySurface:'monitor',frameRate:{ideal:5,max:10}},audio:false});if(stream.getVideoTracks()[0].getSettings().displaySurface!=='monitor'){stream.getTracks().forEach(t=>t.stop());throw new Error('Seleccione una pantalla completa, no una ventana ni pestaña.');}}
if(epoch!==S.aiEpoch){stream.getTracks().forEach(t=>t.stop());return;}S[key]?.getTracks().forEach(t=>t.stop());S[key]=stream;const v=$(key+'-video');v.srcObject=stream;await v.play();$(key+'-state').textContent=key==='camera'?'Cámara activa · sin audio':'Pantalla compartida · solo el monitor elegido';const track=stream.getVideoTracks()[0];for(const type of ['ended','mute','unmute'])track.addEventListener(type,()=>{if(S[key]!==stream)return;$(key+'-state').textContent=type==='unmute'?'Señal recuperada':'Señal interrumpida';if(key==='camera'){resetFaceWindow();S.aiVideoTime=-1;}if(S.active){record(key+'_'+type,type==='unmute'?'Señal recuperada':'Señal de '+(key==='camera'?'cámara':'pantalla')+' interrumpida',type==='unmute'?'info':'attention',`Evento del dispositivo: ${type}. No prueba una acción intencional.`);gate();}prepStatus();if(key==='camera'&&type==='unmute')loadAI();});if(key==='camera'){S.aiVideoTime=-1;resetFaceWindow();await loadAI();}if(S.active){record(key+'_restored','Permiso de '+key+' restablecido','info');gate();}prepStatus();}catch(e){if(S.active)record(key+'_error','No se pudo activar '+key,'attention',e.name+': '+e.message,false);toast(e.message);prepStatus();}}
async function loadAI(){
if(!S.exam||!cfg(S.exam).ai||!live('camera')||(!S.active&&!$('consent')?.checked))return false;
if(S.aiJob)return S.aiJob;
if(S.detector&&S.aiState==='ready'){try{checkAIFrame(S.detector);prepStatus();gate();return true;}catch(e){S.detector.close();S.detector=null;S.aiError=e.message;}}
const epoch=S.aiEpoch;S.aiState='loading';S.aiError='';clearTimeout(S.aiRetryTimer);S.aiRetryTimer=null;aiStatus();prepStatus();gate();
let expired=false,timeout,candidate=null;
const creation=(async()=>{const base='https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.14';const {FaceDetector,FilesetResolver}=await import(base+'/vision_bundle.mjs');const detector=await FaceDetector.createFromOptions(await FilesetResolver.forVisionTasks(base+'/wasm'),{baseOptions:{modelAssetPath:'https://storage.googleapis.com/mediapipe-models/face_detector/blaze_face_short_range/float16/1/blaze_face_short_range.tflite',delegate:'CPU'},runningMode:'VIDEO',minDetectionConfidence:.65});if(expired||epoch!==S.aiEpoch){detector.close();return null;}return detector;})();
const job=(async()=>{try{
candidate=await Promise.race([creation,new Promise((_,reject)=>{timeout=setTimeout(()=>{expired=true;reject(new Error('Tiempo de carga del modelo agotado.'));},30000);})]);
if(epoch!==S.aiEpoch)return false;
if(!candidate||!live('camera')||(!S.active&&!$('consent')?.checked))throw new Error('La cámara o la autorización ya no están disponibles.');
checkAIFrame(candidate);S.detector?.close();S.detector=candidate;candidate=null;S.aiState='ready';S.aiRetryAt=0;resetFaceWindow();
if(S.active)record('ai_restored','Supervisión IA restablecida','info','El modelo volvió a procesar un fotograma. No se analizan retroactivamente los intervalos interrumpidos.',false);
return true;
}catch(e){if(epoch===S.aiEpoch){S.detector?.close();S.detector=null;S.aiState='error';S.aiError=e.message;if(S.active)record('ai_error','No se pudo iniciar o restablecer la supervisión IA','attention',e.message+'. Incidencia técnica, no prueba de fraude.',false);retryAI();}return false;
}finally{expired=true;clearTimeout(timeout);candidate?.close();if(epoch===S.aiEpoch){S.aiJob=null;aiStatus();prepStatus();gate();}}})();
S.aiJob=job;return job;
}
async function begin(){const c=cfg(S.exam);if(!$('consent')?.checked)return toast('Debe aceptar el aviso de captura.');if(c.camera&&!live('camera'))return toast('La cámara es obligatoria.');if(c.screen&&!live('screen'))return toast('Debe compartir una pantalla completa.');if(c.ai&&(!S.detector||S.aiState!=='ready'))return toast('La supervisión obligatoria se está preparando. El examen no ha comenzado.');if(c.ai){try{checkAIFrame(S.detector);}catch(e){S.detector?.close();S.detector=null;S.aiState='error';S.aiError=e.message;aiStatus();prepStatus();retryAI();return toast('No se puede iniciar sin supervisión. Se reintentará automáticamente.');}}if(c.fullscreen)try{await document.documentElement.requestFullscreen();}catch{return toast('Se requiere pantalla completa para iniciar.');}
S.attempt=prepResume||{id:uid(),version:2,student:S.user.email,title:S.exam.title,exam:structuredClone(S.exam),startedAt:Date.now(),deadlineAt:Date.now()+S.exam.minutes*60000,status:'running',answers:{},events:[],review:{state:'Pendiente',note:''},manual:{},localOnly:true,serverVerified:false};S.currentQ=S.exam.questions[0].id;S.active=true;S.submitting=false;S.savingError=false;S.outside=null;S.lastCapture=0;S.faceState=null;S.faceSince=0;S.faceLogged=false;S.mediaCount=(await mediaFor(S.attempt.id)).length;
if(prepResume)record('resume','Intento reanudado','attention','Hubo una interrupción. No se conocen las acciones realizadas mientras el sitio estaba cerrado.',false);else record('start','Examen iniciado','info','Consentimiento aceptado. Hora local del dispositivo; sin validación de servidor.',false);
if(c.ai)record('ai_started','Supervisión IA automática iniciada','info','Obligatoria con cámara. Modelo local de presencia; ausencia o múltiples rostros se remiten a revisión humana.',false);
try{await persist();}catch(e){S.active=false;toast('No se pudo guardar el inicio. No se ha iniciado el examen.');return;}journal();renderExam();attachSignals();capture(S.attempt.events[S.attempt.events.length-1],true);S.timers.push(setInterval(tick,1000));S.timers.push(setInterval(()=>{if(!S.active)return;const e=record('snapshot','Captura periódica','info','Muestreo; no es una grabación continua.',false);capture(e);},c.interval*1000));if(c.ai)S.timers.push(setInterval(faceTick,1000));tick();}
function renderExam(){const a=S.attempt,c=cfg(S.exam);$('nav').hidden=true;view(`<div class="row between"><h1>${esc(a.title)}</h1><span class="tag">Intento ${esc(a.id.slice(0,8))}</span></div><div class="exam-layout"><section><div id="exam-gate" class="notice error" hidden></div><fieldset id="answer-area">${S.exam.questions.map((q,i)=>`<article class="card question" data-question="${esc(q.id)}" id="question-${i}"><span class="tag">Pregunta ${i+1} · ${q.points} puntos</span><h2>${esc(q.text)}</h2>${q.type==='text'?`<textarea data-answer="${esc(q.id)}" rows="6" aria-label="Respuesta pregunta ${i+1}">${esc(a.answers[q.id]||'')}</textarea>`:q.options.map((o,j)=>`<label class="option"><input type="radio" name="answer-${i}" data-answer="${esc(q.id)}" value="${j}" ${a.answers[q.id]===j?'checked':''}>${esc(o)}</label>`).join('')}</article>`).join('')}</fieldset><button data-act="submit">Entregar examen</button></section><aside class="sidebar card"><span class="muted">Tiempo restante</span><div class="clock" id="clock">--:--</div><p id="save-state" class="muted">Guardado local activo</p><div id="exam-media"></div><p id="ai-status" class="muted">${c.ai?'Supervisión automática activa.':'Examen sin supervisión visual.'}</p>${S.user.role!=='estudiante'?'<p><b id="event-count">0</b> eventos registrados</p>':''}<div class="row">${c.camera?button('camera','Reconectar cámara','','secondary small'):''}${c.screen?button('screen','Reconectar pantalla','','secondary small'):''}${c.fullscreen?button('fullscreen','Restaurar pantalla completa','','secondary small'):''}</div><p class="muted">Señales para revisión humana. No hay penalización automática.</p></aside></div>`);mediaAt('exam-media');$('media-dock').querySelector('.grid').style.gridTemplateColumns='1fr';gate();}
function gate(){if(!$('answer-area'))return;const c=cfg(S.exam),missing=[];if(c.camera&&!live('camera'))missing.push('cámara');if(c.screen&&!live('screen'))missing.push('pantalla compartida');if(c.ai&&(!S.detector||S.aiState!=='ready'))missing.push('supervisión automática');$('answer-area').disabled=missing.length>0;$('exam-gate').hidden=!missing.length;$('exam-gate').textContent='Supervisión interrumpida: '+missing.join(', ')+'. La supervisión se reintentará automáticamente; reconecte la cámara o pantalla si hace falta. El tiempo sigue corriendo y sus respuestas se conservan.';}
function tick(){if(!S.active)return;const remaining=S.attempt.deadlineAt-Date.now();if($('clock'))$('clock').textContent=elapsed(remaining);if($('event-count'))$('event-count').textContent=S.attempt.events.length;if(remaining<=0&&!S.submitting)finish(true).catch(fail);}
function record(type,label,level='info',detail='',withCapture=true){if(!S.active||!S.attempt)return null;const a=S.attempt;if(a.events.length>=2500){if(!a.eventLimit){a.eventLimit=true;toast('Límite de eventos alcanzado; el registro adicional está detenido.');}return null;}const q=S.exam.questions.findIndex(x=>x.id===S.currentQ);const e={id:uid(),type,label,level,detail,at:Date.now(),offsetMs:Date.now()-a.startedAt,question:q>=0?q+1:null,media:[]};a.events.push(e);autosave();if(withCapture)capture(e);if($('event-count'))$('event-count').textContent=a.events.length;return e;}
function outside(){if(!S.active||!cfg(S.exam).tabs)return;const away=document.hidden||!document.hasFocus();if(away&&!S.outside){const e=record('outside','Examen fuera de foco o no visible','attention','No se puede identificar la aplicación, pestaña ni URL de destino.');if(e){S.outside={event:e,mono:performance.now()};const interval=S.outside;S.timers.push(setTimeout(()=>{if(S.active&&S.outside===interval){const sample=record('outside_capture','Muestreo durante pérdida de foco','info','Fotograma de las fuentes autorizadas. No determina automáticamente la URL ni la aplicación de destino.',false);capture(sample,true);}},3000));}}if(S.outside){if(document.hidden)S.outside.event.hiddenObserved=true;if(!away)closeOutside();}}
function closeOutside(){if(!S.outside)return;const e=S.outside.event;e.endAt=Date.now();e.durationMs=Math.max(0,performance.now()-S.outside.mono);S.outside=null;record('returned','Regreso al examen','info',`Intervalo fuera: ${elapsed(e.durationMs)}. Puede incluir diálogos del sistema; requiere contexto.`);autosave();}
function attachSignals(){aborter?.abort();aborter=new AbortController();const opt={signal:aborter.signal};document.addEventListener('visibilitychange',outside,opt);window.addEventListener('blur',outside,opt);window.addEventListener('focus',outside,opt);document.addEventListener('fullscreenchange',()=>record(document.fullscreenElement?'fullscreen_in':'fullscreen_out',document.fullscreenElement?'Pantalla completa activada':'Salida de pantalla completa',document.fullscreenElement?'info':'attention'),opt);window.addEventListener('offline',()=>record('offline','Conexión a Internet perdida','attention','Las respuestas siguen guardándose localmente.'),opt);window.addEventListener('online',()=>record('online','Conexión restablecida','info'),opt);window.addEventListener('pagehide',()=>{record('pagehide','Página cerrada o abandonada','attention','Último evento local antes de salir; no identifica el destino.',false);S.attempt.savedAt=Date.now();journal();persist().catch(()=>{});},opt);window.addEventListener('beforeunload',e=>{if(S.active){journal();e.preventDefault();e.returnValue='';}},opt);const area=$('answer-area');area.addEventListener('focusin',e=>{S.currentQ=e.target.closest('[data-question]')?.dataset.question||S.currentQ;},opt);for(const kind of ['copy','cut','paste'])area.addEventListener(kind,e=>{if(!S.active)return;const c=cfg(S.exam);if(!c.clipboard&&!c.blockPaste)return;S.currentQ=e.target.closest('[data-question]')?.dataset.question||S.currentQ;const blocked=kind==='paste'&&c.blockPaste;if(blocked)e.preventDefault();let count=null;if(kind==='paste')count=e.clipboardData?.getData('text/plain')?.length??null;else if(typeof e.target.selectionStart==='number')count=Math.abs(e.target.selectionEnd-e.target.selectionStart);else count=window.getSelection()?.toString().length??null;const ev=record(kind,{copy:'Acción copiar',cut:'Acción cortar',paste:blocked?'Intento de pegado bloqueado':'Acción pegar'}[kind],'attention',`${count===null?'Longitud no disponible':count+' caracteres'}. ${blocked?'Pegado impedido en este campo.':'Acción detectada dentro del examen; no se verifica su origen ni destino.'} No se almacena el texto del portapapeles.`);if(ev){ev.characters=count;ev.blocked=blocked;}},opt);area.addEventListener('drop',e=>{if(cfg(S.exam).blockPaste)e.preventDefault();record('drop','Contenido arrastrado a una respuesta','attention',cfg(S.exam).blockPaste?'Acción bloqueada.':'No se conoce la aplicación de origen.');},opt);}
async function frame(video,width){if(video.readyState<2||!video.videoWidth)throw new Error('No hay fotograma disponible.');const canvas=document.createElement('canvas'),scale=Math.min(1,width/video.videoWidth);canvas.width=Math.round(video.videoWidth*scale);canvas.height=Math.round(video.videoHeight*scale);const ctx=canvas.getContext('2d');ctx.drawImage(video,0,0,canvas.width,canvas.height);return await new Promise((res,rej)=>canvas.toBlob(b=>b?res(b):rej(new Error('No se pudo codificar la foto')),'image/jpeg',.72));}
function capture(e,force=false){if(!e||!S.active)return;const a=S.attempt,c=cfg(S.exam);const sources=[...(c.camera&&c.images?['camera']:[]),...(c.screen?['screen']:[])];if(!sources.length){e.evidenceNote='Capturas no configuradas para este examen.';return;}if(S.capturing||!force&&Date.now()-S.lastCapture<2000){e.evidenceNote='Sin foto adicional: captura próxima en curso o límite de 2 segundos.';return;}if(S.mediaCount>=240){e.evidenceNote='Límite de 240 imágenes alcanzado; no hay captura adicional.';toast(e.evidenceNote);return;}S.capturing=true;S.lastCapture=Date.now();const task=(async()=>{for(const key of sources){if(S.mediaCount>=240)break;try{if(!live(key))throw new Error('Señal no disponible');const v=$(key+'-video'),at=Date.now(),blob=await frame(v,key==='camera'?640:1600);const m={id:uid(),attemptId:a.id,eventId:e.id,kind:key,at,videoTime:v.currentTime,blob,expiresAt:Date.now()+7*86400000};await put('media',m);e.media.push(m.id);S.mediaCount++;}catch(err){e.evidenceNote=(e.evidenceNote||'')+`${key}: ${err.message}. `;if(err.name==='QuotaExceededError'){S.mediaCount=240;toast('Almacenamiento lleno: se detuvo la captura de imágenes.');}}}e.captureNote='Captura del fotograma disponible en ese instante; puede no mostrar el cambio de ventana. No es video continuo.';await persist(a);})().catch(fail).finally(()=>{S.capturing=false;S.pending.delete(task);});S.pending.add(task);}
function faceTick(){
if(!S.active||!cfg(S.exam).ai)return;
if(!live('camera')){resetFaceWindow();gate();return;}
if(!S.detector){if(!S.aiJob&&Date.now()>=S.aiRetryAt)loadAI();gate();return;}
const v=$('camera-video');
if(v.readyState<2||v.currentTime===S.aiVideoTime){if(Date.now()-S.aiLastFrame>5000&&S.aiState!=='stalled'){S.aiState='stalled';resetFaceWindow();record('ai_stalled','Supervisión sin fotogramas nuevos','attention','La cámara no proporcionó un fotograma nuevo durante más de 5 segundos. Puede ser un problema del dispositivo o del navegador.',false);aiStatus();gate();}return;}
try{
const n=S.detector.detectForVideo(v,performance.now()).detections.length;
S.aiVideoTime=v.currentTime;S.aiLastFrame=Date.now();
if(S.aiState!=='ready'){S.aiState='ready';resetFaceWindow();record('ai_restored','Fotogramas de supervisión recuperados','info','El análisis automático se ha restablecido.',false);gate();}
aiStatus();if(S.user?.role!=='estudiante'&&$('ai-status'))$('ai-status').textContent+=` IA local: ${n} rostro(s) detectado(s).`;
const state=n===0?'none':n>1?'multiple':'one';
if(state!==S.faceState){S.faceState=state;S.faceSince=performance.now();S.faceLogged=false;}
if(state!=='one'&&!S.faceLogged&&performance.now()-S.faceSince>=(state==='none'?5000:3000)){S.faceLogged=true;record(state==='none'?'no_face':'multiple_faces',state==='none'?'No se detectó un rostro durante ≥5 s':'Se detectaron varios rostros durante ≥3 s','attention','Resultado aproximado del modelo. Iluminación, postura, imágenes u oclusión pueden producir errores. No identifica a personas.');}
}catch(e){S.detector?.close();S.detector=null;S.aiState='error';S.aiError=e.message;resetFaceWindow();record('ai_error','Supervisión IA interrumpida','attention',e.message+'. Se reintentará automáticamente; no implica fraude.',false);aiStatus();gate();retryAI();}
}
function grade(a){let auto=0,max=0,manual=0,pending=0;for(const q of a.exam.questions){max+=q.points;if(q.type==='text'){if(Number.isFinite(a.manual?.[q.id]))manual+=a.manual[q.id];else pending++;}else if(a.answers[q.id]!==undefined&&a.answers[q.id]===q.correct)auto+=q.points;}return {auto,manual,total:auto+manual,max,pending};}
async function finish(auto=false){if(!S.active||S.submitting)return;if(!auto&&!confirm('¿Entregar? Se conservarán sus respuestas, el historial y las evidencias locales.'))return;S.submitting=true;closeOutside();record(auto?'timeout':'submit',auto?'Entrega por tiempo agotado':'Examen entregado','info','',false);capture(S.attempt.events[S.attempt.events.length-1],true);S.active=false;aborter?.abort();S.timers.forEach(clearInterval);S.timers=[];await Promise.allSettled([...S.pending]);S.attempt.status='submitted';S.attempt.endedAt=Date.now();S.attempt.score=grade(S.attempt);try{await persist();localStorage.removeItem('examia-v2-recovery');}catch(e){S.submitting=false;S.attempt.status='running';S.active=true;journal();toast('No se pudo guardar la entrega. No cierre la página.');attachSignals();S.timers.push(setInterval(tick,1000));if(cfg(S.exam).ai)S.timers.push(setInterval(faceTick,1000));S.timers.push(setInterval(()=>{if(S.active){const e=record('snapshot','Captura periódica','info','Muestreo; no es una grabación continua.',false);capture(e);}},cfg(S.exam).interval*1000));gate();return;}const id=S.attempt.id;stopMedia();if(document.fullscreenElement)document.exitFullscreen().catch(()=>{});$('nav').hidden=false;await review(id);}
function visibleAttempts(items){return S.user.role==='estudiante'?items.filter(a=>a.student===S.user.email):items;}
async function results(){if(S.active)return toast('Entregue primero el examen.');stopMedia();S.attempts=await all('attempts');const items=visibleAttempts(S.attempts).sort((a,b)=>b.startedAt-a.startedAt);view(`<h1>Entregas y evidencias</h1><p class="muted">Solo se muestran intentos de este navegador. No hay sincronización con otras computadoras.</p>${items.length?items.map(a=>{const g=a.status==='legacy'?null:grade(a);return `<article class="card"><div class="row between"><div><span class="tag">${esc(a.status)}</span><h2>${esc(a.title)}</h2><p>${esc(a.student)} · ${date(a.startedAt)}</p><p>${g?`${g.total}/${g.max} puntos${g.pending?' · Desarrollo pendiente':''}`:'Versión anterior: faltan respuestas completas'} ${S.user.role!=='estudiante'?' · '+(a.events||[]).filter(e=>e.level==='attention').length+' señales para revisar':''}</p></div><div class="row">${button('review','Revisar',a.id,'')}${button('delete-attempt','Eliminar datos locales',a.id)}</div></div></article>`;}).join(''):'<div class="card empty">Todavía no hay entregas. Rinda una prueba para generar evidencias reales.</div>'}`);}
function eventHTML(e){return `<article class="event ${e.level==='attention'?'attention':''}" data-event-type="${esc(e.type)}" data-level="${esc(e.level)}"><div class="row between"><b>${esc(e.label)}</b><span class="tag ${e.level==='attention'?'attention':''}">${e.level==='attention'?'Revisar':'Registro'}</span></div><time>${date(e.at)} · +${elapsed(e.offsetMs)}${e.question?' · Pregunta '+e.question:''}</time><p>${esc(e.detail)}</p>${Number.isFinite(e.durationMs)?`<p><b>Duración: ${elapsed(e.durationMs)}</b>${e.hiddenObserved?' · La página también estuvo oculta.':''}</p>`:''}${e.evidenceNote?`<small>${esc(e.evidenceNote)}</small>`:''}<div class="thumbs" data-evidence="${esc(e.id)}"></div>${e.captureNote?`<small>${esc(e.captureNote)}</small>`:''}</article>`;}
async function review(id){if(S.active)return;const a=await get('attempts',id);if(!a)return toast('No se encontró el intento.');if(S.user.role==='estudiante'&&a.student!==S.user.email)return;reviewId=id;if(S.user.role==='estudiante'){
const g=a.status==='legacy'?null:grade(a);
view(`<div class="row between"><h1>Entrega guardada localmente</h1>${button('results','Volver a mis entregas')}</div><section class="card"><h2>${esc(a.title)}</h2><p>${esc(a.student)} · ${date(a.startedAt)}</p><div class="notice warning">Este piloto conserva la entrega en este navegador; todavía no la envía automáticamente al docente. Las incidencias quedan para revisión docente y no generan penalización automática.</div><p>${g?`${g.total}/${g.max} puntos · ${g.pending} pregunta(s) pendiente(s) de revisión.`:'Registro anterior incompleto.'}</p>${a.exam.questions.map((q,i)=>`<details class="card"><summary>Pregunta ${i+1}: ${esc(q.text)}</summary><div class="answer">${esc(q.type==='text'?(a.answers[q.id]??'Sin respuesta'):(q.options[a.answers[q.id]]??'Sin respuesta'))}</div></details>`).join('')}</section>`);return;}
const media=await mediaFor(id),g=a.status==='legacy'?null:grade(a),ev=a.events||[],outsideMs=ev.filter(e=>e.type==='outside').reduce((s,e)=>s+(e.durationMs||0),0);view(`<div class="row between"><div><span class="tag">Informe local · sin validación de servidor</span><h1>${esc(a.title)}</h1><p>${esc(a.student)} · ${date(a.startedAt)}</p></div>${button('results','Volver a entregas')}</div><div class="metrics"><div class="metric"><b>${ev.filter(e=>e.level==='attention').length}</b><span>Señales para revisar</span></div><div class="metric"><b>${media.length}</b><span>Imágenes disponibles</span></div><div class="metric"><b>${elapsed(outsideMs)}</b><span>Fuera de foco / no visible</span></div><div class="metric"><b>${ev.filter(e=>e.type==='paste').length}</b><span>Acciones de pegado</span></div></div><div class="notice warning">Una incidencia no demuestra copia. Los registros locales se pueden modificar y la identidad no está autenticada. Las capturas muestran solo el fotograma disponible; no identifican automáticamente otras pestañas. ${a.status==='legacy'?'La versión anterior no guardaba imágenes ni respuestas completas; no pueden recuperarse retroactivamente.':''}</div><div class="toolbar">${button('export-html','Descargar informe con imágenes',id,'')}${button('export-json','Respaldo JSON con imágenes',id)}${button('export-csv','Exportar incidencias CSV',id)}</div><section class="card"><h2>Respuestas y calificación</h2><p>${g?`<b>${g.total}/${g.max}</b> puntos · ${g.pending} pregunta(s) pendiente(s) de calificación manual.`:'Sin respuestas completas en este registro anterior.'}</p>${a.exam.questions.map((q,i)=>`<details class="card"><summary>Pregunta ${i+1}: ${esc(q.text)} (${q.points} pt)</summary><div class="answer">${esc(q.type==='text'?(a.answers[q.id]??'Sin respuesta'):(q.options[a.answers[q.id]]??'Sin respuesta'))}</div>${S.user.role!=='estudiante'?(q.type==='text'?`<label>Puntos otorgados (0 a ${q.points})<input data-mark="${esc(q.id)}" type="number" min="0" max="${q.points}" step="0.1" value="${a.manual?.[q.id]??''}"></label>`:`<p>Correcta: ${esc(q.options[q.correct])}</p>`):''}</details>`).join('')}${S.user.role!=='estudiante'?`<div class="grid"><label>Estado de revisión<select id="review-state">${['Pendiente','Justificada','Requiere revisión'].map(x=>`<option ${a.review?.state===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Observación del docente<textarea id="review-note">${esc(a.review?.note||'')}</textarea></label></div>${button('save-review','Guardar revisión y notas',id,'')}`:''}</section><div class="row between"><h2>Historial detallado</h2><select id="event-filter" style="width:auto"><option value="all">Todos los eventos</option><option value="attention">Solo señales para revisar</option><option value="clipboard">Copiar / cortar / pegar</option><option value="outside">Foco y visibilidad</option><option value="images">Con imágenes</option><option value="ai">Detecciones IA</option></select></div><div class="timeline">${ev.map(eventHTML).join('')||'<p>Sin eventos disponibles.</p>'}</div>`);for(const m of media){const e=ev.find(e=>e.id===m.eventId);if(!e)continue;const host=[...document.querySelectorAll('[data-evidence]')].find(el=>el.dataset.evidence===m.eventId);if(!host)continue;const url=URL.createObjectURL(m.blob);S.urls.push(url);const b=document.createElement('button');b.dataset.act='image';b.dataset.id=m.id;b.innerHTML=`<img loading="lazy" src="${url}" alt="Captura ${m.kind==='camera'?'de cámara':'de pantalla'}"><small>${m.kind==='camera'?'Cámara':'Pantalla'} · ${esc(date(m.at))}</small>`;host.append(b);}for(const e of ev){if(e.media?.length&&!media.some(m=>m.eventId===e.id)){const host=[...document.querySelectorAll('[data-evidence]')].find(el=>el.dataset.evidence===e.id);if(host)host.textContent='Imagen ya no disponible: pudo caducar o eliminarse.';}}}
async function saveReview(id){const a=await get('attempts',id);a.manual=a.manual||{};for(const input of document.querySelectorAll('[data-mark]')){const q=a.exam.questions.find(q=>q.id===input.dataset.mark);if(!input.value.trim()){delete a.manual[q.id];continue;}const v=Number(input.value);if(!Number.isFinite(v)||v<0||v>q.points)return toast('Revise el rango de las notas manuales.');a.manual[q.id]=v;}a.review={state:$('review-state').value,note:$('review-note').value,at:Date.now(),reviewer:S.user.email};a.score=grade(a);await put('attempts',a);toast('Revisión guardada localmente.');await review(id);}
async function showImage(id){const m=await get('media',id);if(!m)return toast('La imagen ya no está disponible.');const url=URL.createObjectURL(m.blob);S.urls.push(url);$('large-image').src=url;$('image-download').href=url;$('image-download').download=`ExamIA-${m.kind}-${m.id.slice(0,8)}.jpg`;$('image-title').textContent=`${m.kind==='camera'?'Cámara':'Pantalla'} · ${date(m.at)}`;$('image-dialog').showModal();}
function download(name,body,type){const u=URL.createObjectURL(new Blob([body],{type}));const link=document.createElement('a');link.href=u;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(u),60000);}
const toData = blob => new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(r.error);r.readAsDataURL(blob);});
async function exportAttempt(id,format){const a=await get('attempts',id);if(!a)return;const prefix='ExamIA-'+id.slice(0,8);if(format==='csv'){const cell=x=>'"'+String(x??'').replace(/^[=+@\-\t\r]/,"'$&").replaceAll('"','""')+'"';const rows=[['Hora local','Tipo','Evento','Pregunta','Duración segundos','Caracteres','Detalle','Imágenes asociadas'],...a.events.map(e=>[new Date(e.at).toISOString(),e.type,e.label,e.question,e.durationMs===undefined?'':(e.durationMs/1000).toFixed(1),e.characters,e.detail,(e.media||[]).length])];download(prefix+'-incidencias.csv','\ufeff'+rows.map(r=>r.map(cell).join(',')).join('\r\n'),'text/csv;charset=utf-8');return;}
const media=await mediaFor(id);if(media.reduce((s,m)=>s+m.blob.size,0)>80*1024*1024)return toast('Informe de más de 80 MB: exporte CSV y descargue imágenes individualmente.');const encoded=[];for(const m of media){const {blob,...meta}=m;encoded.push({...meta,data:await toData(blob)});}if(format==='json'){download(prefix+'-respaldo.json',JSON.stringify({format:'examia-local-evidence-v2',exportedAt:Date.now(),warning:'Sin autenticación ni integridad de servidor. Datos sensibles. No publicar.',attempt:a,media:encoded},null,2),'application/json');return;}
const photos=e=>encoded.filter(m=>m.eventId===e.id).map(m=>`<figure><img src="${m.data}" alt="${esc(m.kind)}"><figcaption>${esc(m.kind)} · ${esc(date(m.at))}</figcaption></figure>`).join('');const g=a.status==='legacy'?null:grade(a);const html=`<!doctype html><html lang="es"><meta charset="utf-8"><meta name="referrer" content="no-referrer"><title>Informe ExamIA</title><style>body{font:15px/1.55 system-ui;max-width:1060px;margin:30px auto;padding:20px;color:#173146}article,section{border:1px solid #ccd8e0;padding:18px;margin:15px 0;break-inside:avoid}figure{display:inline-block;width:44%;vertical-align:top;margin:2%}img{width:100%}pre{white-space:pre-wrap;overflow-wrap:anywhere}small{color:#526777}h1{font-size:30px}</style><h1>ExamIA · Informe de evidencias</h1><p><b>${esc(a.title)}</b><br>${esc(a.student)} · ${esc(date(a.startedAt))}</p><p><b>Piloto local, no autenticado.</b> La información puede ser modificada por quien controla el dispositivo. Una alerta no demuestra fraude. No se conocen automáticamente las URLs visitadas. Las fotos no son una grabación continua. Este archivo contiene datos sensibles: no publicarlo ni subirlo a un repositorio público.</p><p>Revisión: ${esc(a.review?.state||'Pendiente')} · ${esc(a.review?.note||'')}</p><h2>Respuestas</h2><p>${g?g.total+'/'+g.max+' puntos · '+g.pending+' pendiente(s)':'Registro heredado incompleto'}</p>${a.exam.questions.map((q,i)=>`<section><b>${i+1}. ${esc(q.text)}</b><pre>${esc(q.type==='text'?(a.answers[q.id]??'Sin respuesta'):(q.options[a.answers[q.id]]??'Sin respuesta'))}</pre></section>`).join('')}<h2>Historial y capturas</h2>${a.events.map(e=>`<article><b>${esc(e.label)}</b><p>${esc(date(e.at))}${e.question?' · Pregunta '+e.question:''}${e.durationMs===undefined?'':' · Duración '+elapsed(e.durationMs)}</p><p>${esc(e.detail)}</p><small>${esc(e.evidenceNote||'')} ${esc(e.captureNote||'')}</small><div>${photos(e)}</div></article>`).join('')}</html>`;download(prefix+'-informe.html',html,'text/html;charset=utf-8');}
async function deleteAttempt(id){if(!confirm('¿Eliminar este intento y todas sus imágenes de este navegador? Los informes descargados no se eliminan.'))return;for(const m of await mediaFor(id))await del('media',m.id);await del('attempts',id);try{if(JSON.parse(localStorage.getItem('examia-v2-recovery')||'null')?.id===id)localStorage.removeItem('examia-v2-recovery');}catch{}await results();}
document.addEventListener('input',e=>{const t=e.target;if(t.dataset.exam){S.exam[t.dataset.exam]=t.type==='checkbox'?t.checked:t.dataset.exam==='minutes'?Number(t.value):t.value;}if(t.dataset.setting){S.exam.settings[t.dataset.setting]=t.type==='checkbox'?t.checked:Number(t.value);if(t.dataset.setting==='camera'){S.exam.settings.ai=t.checked;if($('teacher-ai-policy'))$('teacher-ai-policy').textContent=teacherAIText();}}if(t.dataset.q!==undefined){const q=S.exam.questions[Number(t.dataset.q)];if(t.dataset.field&&t.dataset.field!=='type')q[t.dataset.field]=t.dataset.field==='points'?Number(t.value):t.value;if(t.dataset.option!==undefined)q.options[Number(t.dataset.option)]=t.value;if(t.dataset.correct!==undefined)q.correct=Number(t.dataset.correct);}if(t.dataset.answer&&S.active){S.currentQ=t.dataset.answer;S.attempt.answers[t.dataset.answer]=t.type==='radio'?Number(t.value):t.value;autosave();}});
document.addEventListener('change',e=>{const t=e.target;if(t.id==='consent'){if(!t.checked){stopMedia();mediaAt('prep-media');aiStatus();}prepStatus();}if(t.dataset.field==='type'){const q=S.exam.questions[Number(t.dataset.q)];q.type=t.value;q.options=t.value==='text'?[]:t.value==='boolean'?['Verdadero','Falso']:['','','',''];q.correct=0;editor();}if(t.id==='event-filter'){for(const el of document.querySelectorAll('.event[data-event-type]')){const type=el.dataset.eventType,v=t.value;el.hidden=!(v==='all'||v==='attention'&&el.dataset.level==='attention'||v==='clipboard'&&['copy','cut','paste','drop'].includes(type)||v==='outside'&&['outside','returned','outside_capture'].includes(type)||v==='images'&&!!el.querySelector('img')||v==='ai'&&['no_face','multiple_faces','ai_error','ai_started','ai_restored','ai_stalled'].includes(type));}}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-act]');if(!b||b.disabled)return;const act=b.dataset.act,id=b.dataset.id;try{if(act==='enter')enter();else if(act==='home')await home();else if(act==='logout'){if(S.active)return toast('Entregue el examen antes de salir.');S.user=null;login();}else if(act==='create')edit();else if(act==='edit')edit(id);else if(act==='add-question'){S.exam.questions.push({id:uid(),type:'choice',text:'',options:['','','',''],correct:0,points:1});editor();}else if(act==='remove-question'){S.exam.questions.splice(Number(id),1);editor();}else if(act==='save-exam')await saveExam();else if(act==='prepare')await prepare(id);else if(act==='resume'){const a=await get('attempts',id);await prepare(a.exam.id,a);}else if(act==='camera'||act==='screen'){b.disabled=true;try{await setupMedia(act);}finally{b.disabled=false;}}else if(act==='begin'){b.disabled=true;try{await begin();}finally{b.disabled=false;prepStatus();}}else if(act==='fullscreen')await document.documentElement.requestFullscreen();else if(act==='submit')await finish();else if(act==='results')await results();else if(act==='review')await review(id);else if(act==='save-review')await saveReview(id);else if(act==='delete-attempt')await deleteAttempt(id);else if(act==='image')await showImage(id);else if(act==='close-image')$('image-dialog').close();else if(act.startsWith('export-')){b.disabled=true;try{await exportAttempt(id,act.slice(7));}finally{b.disabled=false;}}}catch(err){fail(err);}});
init();
})();
